const r = $input.first().json;
const datas = $('Preparar Datas 30m').first().json;

const msgs_recebidas_dia = r.msgs_recebidas_dia ?? 0;
const msgs_enviadas_dia = r.msgs_enviadas_dia ?? 0;

return [{
  json: {
    data_dia: datas.data_formatada,
    ultima_atualizacao: datas.hoje,
    total_leads: r.total_leads ?? 0,
    leads_novos: r.leads_novos ?? 0,
    leads_recorrentes: r.leads_recorrentes ?? 0,
    total_msgs_recebidas: r.total_msgs_recebidas ?? 0,
    total_msgs_enviadas: r.total_msgs_enviadas ?? 0,
    volume_hoje: r.volume_hoje ?? 0,
    volume_7_dias: r.volume_7_dias ?? 0,
    volume_30_dias: r.volume_30_dias ?? 0,
    instancias_ativas: r.instancias_ativas ?? 0,
    leads_novos_dia: r.leads_novos_dia ?? 0,
    leads_recorrentes_dia: r.leads_recorrentes_dia ?? 0,
    msgs_recebidas_dia,
    msgs_enviadas_dia,
    linha_id: 01
  }
}];

const datas = $('Preparar Datas 30m').first().json;
const items = $input.all();

if (!items || items.length === 0) return [];

// remover grupos
const contatos = items.filter(c => {
  const phone = c.json.phone ?? '';
  return !phone.includes('-group');
});

return contatos.map(c => ({
  json: {
    posicao: c.json.posicao,
    lead_name: c.json.lead_name,
    phone: c.json.phone,
    classificacao: c.json.classificacao,
    tipo_registro: c.json.tipo_registro,
    lead_photo: c.json.lead_photo ?? '',
    status_atividade: c.json.status_atividade,
    score_engajamento: c.json.score_engajamento,
    total_interacoes: c.json.total_interacoes,
    total_mensagens_recebidas: c.json.total_mensagens_recebidas,
    total_mensagens_enviadas: c.json.total_mensagens_enviadas,
    taxa_resposta: c.json.taxa_resposta,
    dias_inativo: c.json.dias_inativo,
    dias_relacionamento: c.json.dias_relacionamento,
    media_msgs_por_dia: c.json.media_msgs_por_dia,
    tem_foto: c.json.tem_foto,
    data_primeiro_contato: c.json.data_primeiro_contato,
    data_ultimo_contato: c.json.data_ultimo_contato,
    idioma: c.json.idioma,
    is_business: c.json.is_business ?? false,
    business_name: c.json.business_name ?? '',
    business_category: c.json.business_category ?? '',
    business_website: c.json.business_website ?? '',
    business_address: c.json.business_address ?? '',
    instance_id: c.json.instance_id,
    ultima_atualizacao: datas.hoje
  }
}));

const agora = new Date();

const spOffset = -3 * 60;
const spNow = new Date(agora.getTime() + (spOffset - (-agora.getTimezoneOffset())) * 60000);

const inicioDia = new Date(spNow);
inicioDia.setHours(0, 0, 0, 0);
const inicioDiaUTC = new Date(inicioDia.getTime() - spOffset * 60000);

const inicio7d = new Date(inicioDiaUTC);
inicio7d.setDate(inicio7d.getDate() - 7);

const inicio30d = new Date(inicioDiaUTC);
inicio30d.setDate(inicio30d.getDate() - 30);

const pad = n => String(n).padStart(2, '0');
const dataFormatada = `${pad(spNow.getDate())}/${pad(spNow.getMonth() + 1)}/${spNow.getFullYear()}`;

return [{
  json: {
    hoje: agora.toISOString(),
    inicio_dia: inicioDiaUTC.toISOString(),
    inicio_7d: inicio7d.toISOString(),
    inicio_30d: inicio30d.toISOString(),
    data_formatada: dataFormatada
  }
}];

const items = $input.all();
if (!items || items.length === 0) return [];
const leads = [];
const grupos = [];
for (const c of items) {
  const r = c.json;
  if (!r) continue;
  if (r.dataset === 'report_leads_grupos') {
    leads.push({
      json: {
        dataset: r.dataset,
        posicao: r.posicao ?? null,
        group_name: r.group_name ?? '',
        group_id: r.group_id ?? '',
        participant_name: r.participant_name ?? '',
        participant_phone: r.participant_phone ?? '',
        total_interacoes: r.total_interacoes ?? 0,
        total_mensagens_enviadas: r.total_mensagens_enviadas ?? 0,
        total_mensagens_recebidas: r.total_mensagens_recebidas ?? 0,
        score_engajamento: r.score_engajamento ?? 0,
        status_atividade: r.status_atividade ?? '',
        dias_inativo: r.dias_inativo ?? 0,
        data_primeiro_evento: r.data_primeiro_evento ?? null,
        data_ultimo_evento: r.data_ultimo_evento ?? null,
        total_midias: r.total_midias ?? 0,
        total_links: r.total_links ?? 0,
        evento_recente: r.evento_recente ?? '',
        tem_foto: r.tem_foto ?? false,
        link_foto: r.link_foto ?? '',
        ultima_atualizacao: r.ultima_atualizacao ?? null
      }
    });
  }
  if (r.dataset === 'report_grupos') {
    grupos.push({
      json: {
        dataset: r.dataset,
        posicao: r.posicao ?? null,
        group_name: r.group_name ?? '',
        group_id: r.group_id ?? '',
        total_participantes_ativos: r.total_participantes_ativos ?? 0,
        total_interacoes: r.total_interacoes ?? 0,
        total_mensagens_recebidas: r.total_mensagens_recebidas ?? 0,
        total_mensagens_enviadas: r.total_mensagens_enviadas ?? 0,
        score_engajamento: r.score_engajamento ?? 0,
        dias_inativo: r.dias_inativo ?? 0,
        data_primeiro_evento: r.data_primeiro_evento ?? null,
        data_ultimo_evento: r.data_ultimo_evento ?? null,
        total_eventos_entrada: r.total_eventos_entrada ?? 0,
        total_eventos_saida: r.total_eventos_saida ?? 0,
        total_midias: r.total_midias ?? 0,
        total_links: r.total_links ?? 0,
        ultima_atualizacao: r.ultima_atualizacao ?? null
      }
    });
  }
}
return [...leads, ...grupos];

function toSP(date) {
  return new Date(
    date.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })
  ).toISOString().replace('Z', '-03:00');
}
const agora = new Date();
const inicioDia = new Date(agora);
inicioDia.setHours(0,0,0,0);
const inicio7d = new Date(agora);
inicio7d.setDate(inicio7d.getDate() - 7);
const inicio30d = new Date(agora);
inicio30d.setDate(inicio30d.getDate() - 30);
return [{
  json: {
    hoje: toSP(agora),
    inicio_dia: toSP(inicioDia),
    inicio_7d: toSP(inicio7d),
    inicio_30d: toSP(inicio30d),
    data_formatada: agora.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' })
  }
}];

const r = $('Montar Dados Diario' in $nodeNames() ? 'Montar Dados Diario' : 'Montar Dados Diario1', 0).json;
const cfg = $input.first().json;

if (!cfg || !cfg.tutor_phone) {
  return [{ json: { skip: true, reason: 'sem tutor_phone' } }];
}

const agentName  = cfg.agent_name  ?? 'jsgrafica';
const tutorPhone = cfg.tutor_phone.replace(/\D/g, '');
const zapiUrl    = (cfg.zapi_url ?? '').replace(/\/+$/, '');
const data = r.data ?? new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const msg =
`\u{1F4CA} *Relat\u00F3rio do dia \u2014 ${agentName}*\n` +
`\u{1F4C5} ${data}\n\n` +
`\u{1F4AC} *Conversas*\n` +
`\u251C Recebidas: ${r.msgs_recebidas_dia ?? 0}\n` +
`\u251C Enviadas: ${r.msgs_enviadas_dia ?? 0}\n` +
`\u2514 Taxa de resposta: ${r.taxa_resposta_dia ?? 0}%\n\n` +
`\u{1F465} *Leads*\n` +
`\u251C Novos hoje: ${r.leads_novos_dia ?? 0}\n` +
`\u251C Recorrentes: ${r.leads_recorrentes_dia ?? 0}\n` +
`\u251C Base total: ${r.total_leads_acumulado ?? 0}\n` +
`\u2514 Engajamento do dia: ${r.taxa_engajamento_dia ?? 0}%\n\n` +
`\u{1F321}\uFE0F *Temperatura da base*\n` +
`\u251C \u{1F7E2} Ativos: ${r.leads_ativos_dia ?? 0}\n` +
`\u251C \u{1F7E1} Mornos: ${r.leads_mornos_dia ?? 0}\n` +
`\u2514 \u{1F534} Frios: ${r.leads_frios_dia ?? 0}`;

return [{ json: {
  tutor_phone: tutorPhone,
  zapi_url: zapiUrl,
  message: msg
} }];
